import{_ as i,a as l,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · 单元 4：综合叙事与自主表达","description":"L73–L96 的学习目标、课时入口和复习方法。","frontmatter":{"title":"第二册：实践与进步 · 单元 4：综合叙事与自主表达","description":"L73–L96 的学习目标、课时入口和复习方法。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"L73–L96 的学习目标、课时入口和复习方法。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第67–72课","link":"/life/english/new-concept/book-2/unit-03/review-part-03"},"next":{"text":"第二册：实践与进步 · 单元 4 语法总结","link":"/life/english/new-concept/book-2/unit-04/grammar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第67–72课","link":"/life/english/new-concept/book-2/unit-03/review-part-03"},"next":{"text":"第二册：实践与进步 · 单元 4 语法总结","link":"/life/english/new-concept/book-2/unit-04/grammar"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/overview.md","filePath":"life/english/new-concept/book-2/unit-04/overview.md"}'),a={name:"life/english/new-concept/book-2/unit-04/overview.md"};function t(s,e,r,h,c,u){return l(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-4-综合叙事与自主表达" tabindex="-1">第二册：实践与进步 · 单元 4：综合叙事与自主表达 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-综合叙事与自主表达" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4：综合叙事与自主表达&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><h2 id="单元导读" tabindex="-1">单元导读 <a class="header-anchor" href="#单元导读" aria-label="Permalink to &quot;单元导读&quot;">​</a></h2><p>L73–L96。第73—96课将前面的句型用于公开信息、紧急沟通、文化说明和虚构叙事。练习不仅检验形式是否正确，也检验读者能否知道信息来源、人物指代、时间范围和结论边界。写作时先用短句建立事实骨架，再把确有关系的内容连接起来；不要为了使用复杂语法而混淆动作执行者。完成本单元后，挑选四个主题分别写一个新段落，并用本册的自查项目修改。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>用定语与分词修饰信息而不造成歧义</li><li>区分证据、声称、承诺和假设</li><li>独立完成有清楚时间线与具体细节的短文</li></ul><h2 id="课时目录" tabindex="-1">课时目录 <a class="header-anchor" href="#课时目录" aria-label="Permalink to &quot;课时目录&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-2/unit-04/lesson-073">Lesson 73 · The record-holder</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-074">Lesson 74 · Out of the limelight</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-075">Lesson 75 · SOS</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-076">Lesson 76 · April Fools&#39; Day</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-077">Lesson 77 · A successful operation</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-078">Lesson 78 · The last one?</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-079">Lesson 79 · By air</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-080">Lesson 80 · The Crystal Palace</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-081">Lesson 81 · Escape</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-082">Lesson 82 · Monster or fish?</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-083">Lesson 83 · After the elections</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-084">Lesson 84 · On strike</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-085">Lesson 85 · Never too old to learn</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-086">Lesson 86 · Out of control</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-087">Lesson 87 · A perfect alibi</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-088">Lesson 88 · Trapped in a mine</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-089">Lesson 89 · A slip of the tongue</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-090">Lesson 90 · What&#39;s for supper?</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-091">Lesson 91 · Three men in a basket</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-092">Lesson 92 · Asking for trouble</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-093">Lesson 93 · A noble gift</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-094">Lesson 94 · Future champions</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-095">Lesson 95 · A fantasy</a></li><li><a href="/life/english/new-concept/book-2/unit-04/lesson-096">Lesson 96 · The dead return</a></li></ul><h2 id="单元知识地图" tabindex="-1">单元知识地图 <a class="header-anchor" href="#单元知识地图" aria-label="Permalink to &quot;单元知识地图&quot;">​</a></h2><ul><li>L73：现在完成时与过去时间。five time 应为 five times；不要把 times 误译成五点钟。</li><li>L74：定语从句与指代。The visitor who recognised the actor smiled. 中 who 作 recognised 的主语，意思是“认出演员的那位游客笑了”。The visitor who he recognised smiled. 也合法：he 作从句主语，who 作宾语，意思是“他认出的那位游客笑了”。若要表达前一种意思，不能写 The visitor who he recognised the actor smiled.；从句已有主语 he 和宾语 the actor，再加 who 会造成成分重复。</li><li>L75：不定式与目的。lie 表躺下，过去式 lay；lay 表放置，过去式 laid，本例需要有宾语的 laid。</li><li>L76：间接引语与视角转换。believe a person 表相信其所说，believe in a person 更偏信任其能力或品格。</li><li>L77：现在完成时与过去时间。enough healthy 的次序不对；形容词后放 enough，如 healthy enough。</li><li>L78：动名词与动词搭配。He stopped to buy cigarettes 表示停下来买烟，意思与停止买烟相反。</li><li>L79：时间、原因与让步从句。despite it was late 结构不对；可用 despite the delay 或 although it was late。</li><li>L80：被动语态与信息重点。was build 错误，build 的过去分词是 built。</li><li>L81：分词修饰与逻辑主语。Dressed as a cleaner, the gate opened 会使分词逻辑主语变成门，形成悬垂结构。</li><li>L82：情态动词的意义与形式。might was 不合结构；过去推测用 might have been。</li><li>L83：将来表达与安排。by June 与 in June 不同：前者指最迟到该时间，后者指在该月内。</li><li>L84：将来进行时与过程。discuss about the offer 多余 about；discuss 直接接宾语。</li><li>L85：不定式与目的。enough confident 语序错误，应为 confident enough；too old 与 very old 意义不同。</li><li>L86：分词修饰与逻辑主语。Hearing a sound, the wheel broke 让 wheel 成听声者，不符合意思。</li><li>L87：间接引语与视角转换。He said ... 不等于 It was proved ...；陈述和证据必须分别标识。</li><li>L88：被动语态与信息重点。through a pipe 指穿过管道内部；across a pipe 则是横跨，不适合输送通道。</li><li>L89：动词、宾语与补足语。Thursday 与 Tuesday 不是同一天；不能只因都以 T 开头而在时间安排中混用。</li><li>L90：分词修饰与逻辑主语。We ran out potatoes 缺 of；Potatoes ran out 是另一种主语安排。</li><li>L91：过去进行时与叙事背景。over the fields 是在田野上方；through the fields 通常表示从田地内部穿行。</li><li>L92：间接引语与视角转换。rude 是形容词，rudely 是副词；meant to be 后用 rude，不是 rudely。</li><li>L93：定语从句与指代。非限制性从句通常不能用 that 替代 which，也不能省略关系代词。</li><li>L94：一般现在时与习惯。practise to float 应改为 practise floating；learn floating 并非此处常用搭配。</li><li>L95：非真实条件句。would can store 错误；能力假设直接用 could，结果可用 would be able to。</li><li>L96：被动语态与信息重点。by 不总是被动执行者：by the river 表在河边，不是河流摆放灯笼。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>能用自己的例子说明上面的语法点；能在不看答案时完成单元自测；能完成至少一项口头表达和一项书面表达，并根据课时点评修订。若做错，不必整单元重学，沿题目链接回到相应课时。</p>',13)])])}const d=i(a,[["render",t]]);export{p as __pageData,d as default};
